"""TRF015: Models declaring tied weights must have a config exposing a tie_word_embeddings flag."""

import ast
from pathlib import Path

from ._helpers import (
    Violation,
    _class_methods,
    _function_argument_names,
    _get_class_assignments,
    _is_direct_pretrained_config_subclass,
    _simple_name,
    full_name,
    iter_pretrained_classes,
)


RULE_ID = ""  # Set by discovery


def _has_nonempty_tied_weights_keys(class_node: ast.ClassDef) -> bool:
    """Return True when the class declares a non-empty ``_tied_weights_keys`` attribute."""
    value = _get_class_assignments(class_node).get("_tied_weights_keys")
    if value is None:
        return False
    if isinstance(value, (ast.List, ast.Tuple, ast.Set)):
        return len(value.elts) > 0
    if isinstance(value, ast.Dict):
        return len(value.keys) > 0
    if isinstance(value, ast.Constant) and value.value is None:
        return False
    # Any other expression (a name, call, comprehension, ...) is assumed to declare tied weights.
    return True


def _explicit_config_class_name(class_node: ast.ClassDef) -> str | None:
    """Return the simple name assigned to ``config_class`` on the model class, if any."""
    value = _get_class_assignments(class_node).get("config_class")
    if isinstance(value, (ast.Name, ast.Attribute)):
        try:
            return _simple_name(full_name(value))
        except ValueError:
            return None
    return None


def _config_annotation_name(class_node: ast.ClassDef) -> str | None:
    """Return the simple name of the ``config`` parameter annotation in ``__init__``, if any."""
    init = _class_methods(class_node).get("__init__")
    if init is None:
        return None
    for arg in list(init.args.args) + list(init.args.kwonlyargs):
        if arg.arg == "config" and arg.annotation is not None:
            try:
                return _simple_name(full_name(arg.annotation))
            except ValueError:
                return None
    return None


def _common_prefix_len(left: str, right: str) -> int:
    length = 0
    for left_char, right_char in zip(left, right):
        if left_char != right_char:
            break
        length += 1
    return length


def _config_classes(config_tree: ast.Module) -> dict[str, ast.ClassDef]:
    return {node.name: node for node in config_tree.body if isinstance(node, ast.ClassDef)}


def _config_defines_tie_word_embeddings(config_node: ast.ClassDef) -> bool:
    """Return True if the config class exposes a ``tie_word_embeddings`` flag."""
    for item in config_node.body:
        if isinstance(item, ast.Assign):
            for target in item.targets:
                if isinstance(target, ast.Name) and target.id == "tie_word_embeddings":
                    return True
        elif isinstance(item, ast.AnnAssign):
            if isinstance(item.target, ast.Name) and item.target.id == "tie_word_embeddings":
                return True

    init = _class_methods(config_node).get("__init__")
    if init is not None:
        if "tie_word_embeddings" in _function_argument_names(init):
            return True
        for sub_node in ast.walk(init):
            if (
                isinstance(sub_node, ast.Attribute)
                and sub_node.attr == "tie_word_embeddings"
                and isinstance(sub_node.value, ast.Name)
                and sub_node.value.id == "self"
            ):
                return True
    return False


def _resolve_target_config(
    model_name: str,
    explicit_name: str | None,
    annotated_name: str | None,
    config_infos: list[tuple[Path, ast.Module]],
) -> ast.ClassDef | None:
    """Resolve the configuration class for a model class across companion config files.

    Resolution order: an explicit ``config_class`` assignment, a ``config`` type annotation,
    then the config class sharing the longest prefix with the model class name. Companion files
    are consulted in preference order so exact-suffix matches win ties.
    """
    for name in (explicit_name, annotated_name):
        if not name:
            continue
        for _, config_tree in config_infos:
            classes = _config_classes(config_tree)
            if name in classes:
                return classes[name]

    best: ast.ClassDef | None = None
    best_len = 0
    for _, config_tree in config_infos:
        for class_name, class_node in _config_classes(config_tree).items():
            if not class_name.endswith("Config"):
                continue
            shared = _common_prefix_len(model_name, class_name)
            if shared > best_len:
                best_len = shared
                best = class_node
    if best is not None and best_len > 0:
        return best
    return None


def check(tree: ast.Module, file_path: Path, source_lines: list[str]) -> list[Violation]:
    if not file_path.name.startswith(("modeling_", "modular_")):
        return []

    model_classes = [
        node for node in iter_pretrained_classes(tree, source_lines, RULE_ID) if _has_nonempty_tied_weights_keys(node)
    ]
    if not model_classes:
        return []

    # Import lazily to avoid an import cycle: mlinter imports this module during rule discovery.
    from .mlinter import _find_companion_files

    config_infos: list[tuple[Path, ast.Module]] = []
    for companion in _find_companion_files(file_path):
        try:
            config_infos.append((companion, ast.parse(companion.read_text(encoding="utf-8"))))
        except (OSError, SyntaxError, ValueError):
            continue
    if not config_infos:
        return []

    violations: list[Violation] = []
    for node in model_classes:
        config_node = _resolve_target_config(
            node.name,
            _explicit_config_class_name(node),
            _config_annotation_name(node),
            config_infos,
        )
        if config_node is None:
            continue
        # Only direct PreTrainedConfig subclasses own the tie_word_embeddings flag. Configs that
        # inherit from another *Config base are assumed to receive it from their parent.
        if not _is_direct_pretrained_config_subclass(config_node):
            continue
        if _config_defines_tie_word_embeddings(config_node):
            continue

        violations.append(
            Violation(
                file_path=file_path,
                line_number=node.lineno,
                message=(
                    f"{RULE_ID}: {node.name} declares _tied_weights_keys but its configuration class "
                    f"{config_node.name} does not expose a tie_word_embeddings flag to disable weight tying."
                ),
            )
        )

    return violations
